import React, { useState, useEffect } from 'react';
import api from '../services/api';

const AnalyticsDashboard = () => {
    const [analyticsData, setAnalyticsData] = useState({
        totalUsers: 0,
        totalMatches: 0,
        totalMessages: 0,
        activeUsers: 0,
        avgDistance: '12 km' // Placeholder for distance
    });
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchAnalytics = async () => {
            try {
                // Assuming API has an endpoint /admin/stats configured in api.js or direct fetch
                const response = await fetch(`${process.env.REACT_APP_API_URL || `http://${window.location.hostname}:5000`}/admin/stats`);
                if (response.ok) {
                    const data = await response.json();
                    setAnalyticsData({
                        totalUsers: data.total_users || 0,
                        totalMatches: data.total_matches || 0,
                        totalMessages: data.total_messages || 0,
                        activeUsers: data.active_users || 0,
                        avgDistance: '14.2 km' // Placeholder until backend calculates geospatial distances
                    });
                }
            } catch (err) {
                console.error("Failed to fetch analytics:", err);
            } finally {
                setLoading(false);
            }
        };

        fetchAnalytics();
    }, []);

    if (loading) return <div style={{ padding: '30px' }}>Loading analytics...</div>;

    return (
        <div style={{ padding: '30px', maxWidth: '1200px', margin: '0 auto' }}>
            <h1 style={{ fontSize: '2rem', color: '#1f2937', marginBottom: '30px' }}>📈 Analytics Dashboard</h1>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '40px' }}>
                <div style={cardStyle('#3b82f6')}>
                    <h3>Total Users</h3>
                    <p>{analyticsData.totalUsers}</p>
                </div>
                <div style={cardStyle('#e11d48')}>
                    <h3>Total Matches</h3>
                    <p>{analyticsData.totalMatches}</p>
                </div>
                <div style={cardStyle('#10b981')}>
                    <h3>Total Messages</h3>
                    <p>{analyticsData.totalMessages}</p>
                </div>
                <div style={cardStyle('#f59e0b')}>
                    <h3>Active Users</h3>
                    <p>{analyticsData.activeUsers}</p>
                </div>
                <div style={cardStyle('#8b5cf6')}>
                    <h3>Avg. Distance</h3>
                    <p>{analyticsData.avgDistance}</p>
                </div>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
                {/* Placeholder Charts */}
                <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0,0,0,0.1)', height: '300px', display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column' }}>
                    <h3 style={{ alignSelf: 'flex-start', margin: '0 0 20px 0', color: '#374151' }}>📊 User Growth Trends</h3>
                    <div style={{ width: '100%', height: '80%', background: 'linear-gradient(180deg, rgba(59,130,246,0.2) 0%, rgba(255,255,255,0) 100%)', borderBottom: '2px solid #3b82f6', position: 'relative' }}>
                        <div style={{ position: 'absolute', bottom: '20%', left: '10%', width: '10px', height: '40%', backgroundColor: '#3b82f6' }}></div>
                        <div style={{ position: 'absolute', bottom: '20%', left: '30%', width: '10px', height: '50%', backgroundColor: '#3b82f6' }}></div>
                        <div style={{ position: 'absolute', bottom: '20%', left: '50%', width: '10px', height: '70%', backgroundColor: '#3b82f6' }}></div>
                        <div style={{ position: 'absolute', bottom: '20%', left: '70%', width: '10px', height: '60%', backgroundColor: '#3b82f6' }}></div>
                        <div style={{ position: 'absolute', bottom: '20%', left: '90%', width: '10px', height: '90%', backgroundColor: '#3b82f6' }}></div>
                    </div>
                </div>

                <div style={{ backgroundColor: 'white', padding: '20px', borderRadius: '12px', boxShadow: '0 4px 6px rgba(0,0,0,0.1)', height: '300px', display: 'flex', alignItems: 'center', justifyContent: 'center', flexDirection: 'column' }}>
                    <h3 style={{ alignSelf: 'flex-start', margin: '0 0 20px 0', color: '#374151' }}>❤️ Match Engagement</h3>
                    <div style={{ width: '100%', height: '80%', background: 'linear-gradient(180deg, rgba(225,29,72,0.2) 0%, rgba(255,255,255,0) 100%)', borderBottom: '2px solid #e11d48', position: 'relative' }}>
                         <div style={{ position: 'absolute', bottom: '20%', left: '15%', width: '20px', height: '30%', backgroundColor: '#e11d48', borderRadius: '10px 10px 0 0' }}></div>
                         <div style={{ position: 'absolute', bottom: '20%', left: '45%', width: '20px', height: '60%', backgroundColor: '#e11d48', borderRadius: '10px 10px 0 0' }}></div>
                         <div style={{ position: 'absolute', bottom: '20%', left: '75%', width: '20px', height: '80%', backgroundColor: '#e11d48', borderRadius: '10px 10px 0 0' }}></div>
                    </div>
                </div>
            </div>
        </div>
    );
};

const cardStyle = (color) => ({
    backgroundColor: 'white',
    padding: '20px',
    borderRadius: '12px',
    boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
    borderLeft: `4px solid ${color}`,
    display: 'flex',
    flexDirection: 'column'
});

export default AnalyticsDashboard;
